DROP TABLE IF EXISTS `runner`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `runner` (
  `runner_id` int NOT NULL AUTO_INCREMENT,
  `start_number` int DEFAULT NULL,
  `name` varchar(100) NOT NULL,
  `nickname` varchar(45) DEFAULT NULL,
  `gender` varchar(1) NOT NULL,
  `birthday` date DEFAULT NULL,
  `is_kid` varchar(1) DEFAULT NULL,
  `home_address` varchar(100) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `organisation_id` int DEFAULT NULL,
  `first_race_id` int DEFAULT NULL,
  PRIMARY KEY (`runner_id`),
  UNIQUE KEY `name_UNIQUE` (`name`),
  UNIQUE KEY `start_number_UNIQUE` (`start_number`),
  KEY `fk_organisation_idx` (`organisation_id`),
  KEY `fk_race_idf` (`first_race_id`),
  CONSTRAINT `fk_organisation` FOREIGN KEY (`organisation_id`) REFERENCES `organisation` (`organisation_id`),
  CONSTRAINT `fk_race_idf` FOREIGN KEY (`first_race_id`) REFERENCES `race` (`race_id`),
