CREATE DEFINER=`root`@`localhost` PROCEDURE `InsertNewRunnerFromImport`()
BEGIN
	insert into runner(name, gender )
	SELECT ri.runner_name
		  ,ri.gender as gender
	FROM vlt.race_import ri
	where ri.runner_id is null;
END ;;
