DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `InsertParticipationFromImport`(in P_RoundId int)
BEGIN
   declare L_cnt int;
   
   select count(*)
	 into L_cnt 
	 from season s
	 join round_data rd   on (s.season_id = rd.season_id)
	 join race ra         on (rd.round_id = ra.round_id)
	 join participation p on (p.race_id = ra.race_id)
	 join runner r        on (p.runner_id = r.runner_id)
	where rd.round_id = P_RoundId;

	select concat('Vec ima ', L_cnt, ' insertovanih') as poruka;

	if L_cnt = 0 then
       select 'Usao je u insert' as poruka;
	   insert into participation(race_id, runner_id, time, points, avg_pace)
	   select (select race_id 
				 from race
				where round_id = P_RoundId 
				  and gender   = ri.gender
				  and length   = ri.length) as race_id
			  ,runner_id, time, points, avg_pace
		 from vlt.race_import ri;
	 end if;
END ;;
DELIMITER ;
