DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `InsertRoundAndDefaultRaces`(in P_SeasonId int, in P_StartDate varchar(10), in P_8km boolean)
BEGIN
   DECLARE L_MaxRoundId int;
   DECLARE L_MaxRoundNumber int;
   
   select max(round_number) into L_MaxRoundNumber from round_data;-- where season_id = P_SeasonId ;
   
   insert into round_data(season_id, round_number, start_date, location) 
               values (P_SeasonId, L_MaxRoundNumber + 1, STR_TO_DATE(P_StartDate,'%d.%m.%Y'), 'Lazin park' );
      
   SELECT max(round_id) INTO L_MaxRoundId FROM round_data;

   insert race(round_id, length, gender) values (L_MaxRoundId, 2, 'F');
   insert race(round_id, length, gender) values (L_MaxRoundId, 4, 'F');
   insert race(round_id, length, gender) values (L_MaxRoundId, 2, 'M');
   insert race(round_id, length, gender) values (L_MaxRoundId, 4, 'M');
   if P_8km then
	insert race(round_id, length, gender) values (L_MaxRoundId, 8, 'M');
	insert race(round_id, length, gender) values (L_MaxRoundId, 8, 'F');
   end if;
   
   select concat('Kreirano je ', L_MaxRoundNumber + 1, ' kolo. Id kola je ',L_MaxRoundId) as poruka;
   
END ;;
DELIMITER ;
