      ,avg_pace    = STR_TO_DATE(avg_pace_var, '%i:%s')
      ,runner_name = trim(runner_name);
      
   update race_import ri
   set runner_id = (select r.runner_id from runner r where r.name = runner_name);
   
   delete from race_import 
   where runner_name is null;
END ;;
